async function validateOwnerToken(token) {
  if (!token) return false;
  try {
    const identity = await whoAmI(token);
    return Boolean(identity?.roles?.includes?.('owner'));
  } catch {
    return false;
  }
}

async function handleOwnerUnlock(event) {
  event.preventDefault();
  event.stopImmediatePropagation();
  if (ownerActionBusy) return;
  ownerActionBusy = true;
  ownerError('');
  const button = $('unlockOwner');
  if (button) { button.disabled = true; button.textContent = 'VALIDANDO DESAPLICAXI…'; }
  try {
    const existing = localStorage.getItem(OWNER_TOKEN_KEY);
    if (existing && await validateOwnerToken(existing)) {
      setOwnerCompatUnlocked();
      location.href = ownerRoute();
      return;
    }
    localStorage.removeItem(OWNER_TOKEN_KEY);
    clearOwnerCompat();
    const setup = $('ownerSecret')?.value.trim().toUpperCase() || '';
    if (!/^SETUP-[A-Z0-9]{20,64}$/.test(setup)) {
      ownerError('Pega el código SETUP de vinculación OWNER global.');
      return;
    }
    const result = await claimGlobalOwner(setup);
    localStorage.setItem(OWNER_TOKEN_KEY, result.sessionToken);
    if ($('ownerSecret')) $('ownerSecret').value = '';
    showOwnerClaim(result);
  } catch (error) {
    ownerError(error?.message === 'DESAPLICAXI_TIMEOUT'
      ? 'DESAPLICAXI tardó demasiado en responder. Reintenta cuando mejore la conexión.'
      : 'El código SETUP es inválido, ya fue usado o venció.');
  } finally {
    ownerActionBusy = false;
    if (button) { button.disabled = false; button.textContent = 'VINCULAR / ENTRAR COMO OWNER'; }
  }
}

async function handleOwnerRecovery(event) {
  event.preventDefault();
  event.stopImmediatePropagation();
  if (ownerActionBusy) return;
  const dx = $('ownerRecoverDx')?.value.trim().toUpperCase() || '';
  const vcr = $('ownerRecoverVcr')?.value.trim().toUpperCase() || '';
  if (!dx.startsWith('DX-') || !vcr.startsWith('VCR-')) {
    ownerError('Escribe tu DX OWNER y tu VCR OWNER.');
    return;
  }
  ownerActionBusy = true;
  ownerError('');
  const button = $('recoverOwner');
  if (button) { button.disabled = true; button.textContent = 'RECUPERANDO OWNER…'; }
  try {
    const result = await recoverGlobalIdentity(dx, vcr);
    const identity = await whoAmI(result.sessionToken);
    if (!identity?.roles?.includes?.('owner')) {
      await logoutGlobal(result.sessionToken).catch(() => {});
      throw new Error('RECOVERED_IDENTITY_NOT_OWNER');
    }
    localStorage.setItem(OWNER_TOKEN_KEY, result.sessionToken);
    if ($('ownerRecoverVcr')) $('ownerRecoverVcr').value = '';
    setOwnerCompatUnlocked();
    showOwnerClaim(result);
  } catch (error) {
    ownerError(error?.message === 'DESAPLICAXI_TIMEOUT'
      ? 'DESAPLICAXI tardó demasiado en responder. Reintenta cuando mejore la conexión.'
      : 'No se pudo recuperar OWNER. Revisa DX + VCR; la VCR anterior deja de servir si ya fue rotada.');
  } finally {
    ownerActionBusy = false;
    if (button) { button.disabled = false; button.textContent = 'RECUPERAR OWNER EN ESTE DISPOSITIVO'; }
  }
}

function saveInviteLocal(invite) {
  let items = [];
  try { items = JSON.parse(localStorage.getItem(OWNER_INVITES_KEY) || '[]'); } catch {}
  if (!Array.isArray(items)) items = [];
  items.unshift(invite);
  localStorage.setItem(OWNER_INVITES_KEY, JSON.stringify(items.slice(0, 40)));
}

function setInviteButtons(enabled) {
  ['copyCode', 'copyLink', 'shareInvite', 'copyMessage', 'openHostRoom'].forEach((id) => {
    const el = $(id);
    if (el) el.disabled = !enabled;
  });
}

function buildMamiLink(base, code, room) {
  return `${buildInviteUrl(base, code, room)}&mode=mami`;
}

function inviteShareText(invite) {
  if (invite.mode === 'mami') {
    return `Mami, toca este enlace. VIVA CUBA se prepara sola y después pulsa “LLAMAR A AXIEL”.\n\n${invite.link}`;
  }
  return buildInviteMessage(invite.code, invite.link);
}

async function handleGlobalInvite(event, mode = 'standard') {
  event.preventDefault();
  event.stopImmediatePropagation();
  if (ownerActionBusy) return;
  const token = localStorage.getItem(OWNER_TOKEN_KEY);
  if (!token || !(await validateOwnerToken(token))) {
    clearOwnerCompat();
    ownerError('La sesión OWNER global no es válida. Vuelve a vincular el Command Center.');
    location.href = ownerRoute();
    return;
  }
  ownerActionBusy = true;
  const button = $('generateInvite');
  if (button) { button.disabled = true; button.textContent = 'GENERANDO INVITACIÓN GLOBAL…'; }
  setInviteButtons(false);
  try {
    const issued = await issueGlobalInvitation(token, mode === 'mami' ? 'MODO MAMI · CUBA' : 'VIVA CUBA OWNER');
    const room = generateRoomId();
    const link = mode === 'mami'
      ? buildMamiLink(publicBaseUrl(), issued.code, room)
      : buildInviteUrl(publicBaseUrl(), issued.code, room);
    currentGlobalInvite = {
      code: issued.code,
      room,
      link,
      mode,
      createdAt: new Date().toISOString(),
      expiresAt: issued.expiresAt,
      status: 'issued-global',
    };
    $('generatedCode').textContent = currentGlobalInvite.code;
    $('generatedRoom').textContent = room;
    $('generatedLink').textContent = link;
    saveInviteLocal(currentGlobalInvite);
    setInviteButtons(true);
    const status = $('ownerStatus');
    if (status) {
      status.textContent = mode === 'mami'
        ? 'Enlace Mami emitido por DESAPLICAXI · listo para enviar'
        : 'Invitación global emitida por DESAPLICAXI';
      status.classList.remove('hidden');
    }
  } catch {
    const status = $('ownerStatus');
    if (status) {
      status.textContent = 'No se pudo emitir la invitación global. No se generó ningún VCM local falso.';
      status.classList.remove('hidden');
    }
  } finally {
    ownerActionBusy = false;
    if (button) { button.disabled = false; button.textContent = 'GENERAR NUEVA INVITACIÓN'; }
  }
}

async function copy(text) {
  try { await navigator.clipboard.writeText(text); }
  catch { window.prompt('Copia este contenido:', text); }
}

function interceptInviteAction(id, fn) {
  $(id)?.addEventListener('click', (event) => {
    if (!currentGlobalInvite) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    fn(currentGlobalInvite);
  }, { capture: true });
}

$('unlockOwner')?.addEventListener('click', handleOwnerUnlock, { capture: true });
$('recoverOwner')?.addEventListener('click', handleOwnerRecovery, { capture: true });
$('ownerSecret')?.addEventListener('keydown', (event) => {
  if (event.key !== 'Enter') return;
  event.preventDefault();
  event.stopImmediatePropagation();
  handleOwnerUnlock(event);
}, { capture: true });
$('generateInvite')?.addEventListener('click', (event) => handleGlobalInvite(event, 'standard'), { capture: true });
$('generateMamiInvite')?.addEventListener('click', (event) => handleGlobalInvite(event, 'mami'), { capture: true });

interceptInviteAction('copyCode', (invite) => copy(invite.code));
interceptInviteAction('copyLink', (invite) => copy(invite.link));
interceptInviteAction('copyMessage', (invite) => copy(inviteShareText(invite)));
interceptInviteAction('shareInvite', async (invite) => {
  const text = inviteShareText(invite);
  if (navigator.share) {
    try { await navigator.share({ title: 'Invitación VIVA CUBA', text, url: invite.link }); return; }
    catch (error) { if (error?.name === 'AbortError') return; }
  }
  await copy(text);
});
interceptInviteAction('openHostRoom', (invite) => {
  window.open(`https://meet.jit.si/${encodeURIComponent(invite.room)}`, '_blank', 'noopener,noreferrer');
});

$('exitOwner')?.addEventListener('click', () => {
  const token = localStorage.getItem(OWNER_TOKEN_KEY);
  setTimeout(() => {
    if (localStorage.getItem(OWNER_PERSIST_KEY) === 'unlocked') return;
    localStorage.removeItem(OWNER_TOKEN_KEY);
    if (token) logoutGlobal(token).catch(() => {});
  }, 0);
}, { capture: true });

configureGateCopy();
const existingToken = localStorage.getItem(OWNER_TOKEN_KEY);
if (!existingToken) {
  clearOwnerCompat();
} else {
  validateOwnerToken(existingToken).then((ok) => {
    if (!ok) {
      localStorage.removeItem(OWNER_TOKEN_KEY);
      clearOwnerCompat();
      if (new URLSearchParams(location.search).get('mode') === 'owner' || location.hash.toLowerCase() === '#owner') {
        location.reload();
      }
    }
  });
}

:root {
  color-scheme: dark;
  --bg: #030907;
  --panel: rgba(8, 24, 17, .92);
  --panel-2: rgba(11, 35, 24, .9);
  --line: rgba(106, 255, 169, .18);
  --green: #69f0a5;
  --green-2: #2dd477;
  --text: #ecfff4;
  --muted: #9fb9ab;
  --danger: #ff7c87;
  --warning: #ffd67a;
  --shadow: 0 24px 70px rgba(0,0,0,.35);
}
* { box-sizing: border-box; }
html { min-height: 100%; background: var(--bg); }
body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 20% 0%, rgba(30, 190, 102, .13), transparent 30rem),
    linear-gradient(160deg, #020705 0%, #07150f 55%, #020705 100%);
}
body::before {
  content: "";
  position: fixed; inset: 0; pointer-events: none; opacity: .18;
  background-image: linear-gradient(rgba(105,240,165,.07) 1px, transparent 1px), linear-gradient(90deg, rgba(105,240,165,.07) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, black, transparent 75%);
}
button, input { font: inherit; }
button { cursor: pointer; }
button:disabled { opacity: .45; cursor: not-allowed; }
.page-shell { width: min(920px, 100%); margin: 0 auto; padding: max(20px, env(safe-area-inset-top)) 18px 48px; }
.brandbar { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin: 12px 0 24px; }
h1, h2, p { margin-top: 0; }
h1 { font-size: clamp(2rem, 8vw, 3.8rem); margin-bottom: 0; letter-spacing: -.04em; }
h2 { font-size: clamp(1.35rem, 5vw, 2rem); margin-bottom: 8px; }
.eyebrow { color: var(--green); font-size: .72rem; font-weight: 800; letter-spacing: .15em; margin-bottom: 6px; }
.pilot-badge { flex: 0 0 auto; border: 1px solid var(--line); border-radius: 999px; padding: 8px 11px; color: var(--green); font-size: .7rem; font-weight: 800; background: rgba(5,20,13,.7); }
.panel { border: 1px solid var(--line); border-radius: 24px; padding: 22px; margin-bottom: 16px; background: linear-gradient(160deg, var(--panel), rgba(3,12,8,.94)); box-shadow: var(--shadow); backdrop-filter: blur(16px); }
.panel-heading { margin-bottom: 20px; }
.muted, .microcopy { color: var(--muted); line-height: 1.55; }
.microcopy { font-size: .82rem; margin: 8px 0 18px; }
label, .label { display: block; color: var(--muted); font-size: .78rem; font-weight: 750; text-transform: uppercase; letter-spacing: .08em; margin: 16px 0 8px; }
input { width: 100%; min-height: 52px; color: var(--text); background: #06110c; border: 1px solid rgba(105,240,165,.22); border-radius: 14px; padding: 0 14px; outline: none; }
input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(105,240,165,.1); }
.input-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; }
button { min-height: 46px; border: 0; border-radius: 14px; padding: 0 16px; font-weight: 850; letter-spacing: .02em; }
.primary { color: #021008; background: linear-gradient(135deg, var(--green), var(--green-2)); box-shadow: 0 12px 30px rgba(45,212,119,.17); }
.secondary { color: var(--green); background: rgba(105,240,165,.08); border: 1px solid var(--line); }
.danger-ghost { color: var(--danger); background: transparent; border: 1px solid rgba(255,124,135,.25); }
.big { width: 100%; min-height: 58px; margin-top: 22px; }
.compact { min-height: 36px; padding: 0 11px; font-size: .76rem; }
.call-button { width: 100%; min-height: 64px; font-size: 1rem; }
.notice { border-radius: 14px; padding: 12px 14px; margin: 12px 0; line-height: 1.4; border: 1px solid transparent; }
.notice.success { color: #bcffd8; background: rgba(45,212,119,.08); border-color: rgba(45,212,119,.2); }
.notice.error { color: #ffc5cb; background: rgba(255,124,135,.08); border-color: rgba(255,124,135,.22); }
.notice.warning { color: #ffe9ac; background: rgba(255,214,122,.07); border-color: rgba(255,214,122,.18); }
.hidden { display: none !important; }
.pilot-note { color: var(--muted); margin-top: 18px; }
.pilot-note summary { cursor: pointer; color: var(--green); }
.status-strip { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: .82rem; margin: 0 4px 12px; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); box-shadow: 0 0 12px var(--green); }
.status-dot.offline { background: var(--danger); box-shadow: none; }
.dx-card { display: grid; gap: 10px; background: rgba(105,240,165,.055); border: 1px solid var(--line); border-radius: 18px; padding: 16px; }
.dx-card span { color: var(--muted); font-size: .8rem; }
.dx-card strong { font-size: clamp(1.45rem, 6vw, 2.2rem); letter-spacing: .08em; color: var(--green); overflow-wrap: anywhere; }
.info-grid, .owner-status-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 14px; }
.info-grid > div, .owner-status-grid > div { padding: 14px; border-radius: 14px; background: rgba(255,255,255,.025); }
.info-grid strong, .owner-status-grid strong { display: block; overflow-wrap: anywhere; }
.actions-panel, .button-stack { display: grid; gap: 10px; }
.generated-grid { margin-top: 18px; }
.copy-field { display: flex; gap: 8px; align-items: center; border: 1px solid var(--line); background: #06110c; border-radius: 14px; padding: 10px 10px 10px 14px; }
.copy-field code { flex: 1; color: var(--green); overflow-wrap: anywhere; word-break: break-word; }
.link-field { align-items: flex-start; }
.text-link { color: var(--green); text-decoration: none; }
.owner-topbar { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin: 8px 0 16px; }
.owner-actions { margin-top: 16px; }
.command-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }
.command-grid article { min-height: 112px; padding: 16px; border-radius: 16px; border: 1px solid var(--line); background: rgba(105,240,165,.035); display: flex; flex-direction: column; justify-content: space-between; gap: 12px; }
.command-grid article strong { color: var(--green); }
.command-grid article span { color: var(--muted); font-size: .82rem; line-height: 1.4; }
.history-list, .audit-list { display: grid; gap: 10px; }
.history-item, .audit-row { border: 1px solid var(--line); border-radius: 16px; padding: 14px; background: rgba(255,255,255,.025); }
.history-item { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.history-item > div:first-child, .audit-row { display: grid; gap: 5px; }
.history-item span, .audit-row span { color: var(--muted); font-size: .78rem; line-height: 1.4; }
.history-actions { display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-end; }
@media (max-width: 620px) {
  .brandbar, .owner-topbar { align-items: flex-start; flex-direction: column; }
  .input-row { grid-template-columns: 1fr; }
  .info-grid, .owner-status-grid, .command-grid { grid-template-columns: 1fr; }
  .panel { padding: 18px; border-radius: 20px; }
  .copy-field { align-items: stretch; flex-direction: column; }
  .history-item { align-items: stretch; flex-direction: column; }
  .history-actions { justify-content: stretch; }
  .history-actions button { flex: 1; }
}


